/** Keyless production-dialog acceptance with controlled profile replies and frozen sample pages. */
async page => {
  const assert = (value, message) => { if (!value) throw new Error(message) }
  const errors = [], onError = error => errors.push(error.message)
  page.on('pageerror', onError)
  try {
    await page.reload({ waitUntil: 'domcontentloaded' })
    await page.setViewportSize({ width: 1440, height: 960 })
    const dialog = page.getByRole('dialog', { name: '风格档案', exact: true })
    await page.getByRole('button', { name: '查看完整档案', exact: true }).click()
    await dialog.waitFor()
    const a = dialog.getByRole('checkbox').nth(0), b = dialog.getByRole('checkbox').nth(1)
    await page.waitForFunction(() => !document.querySelector('.vc-profile-dialog input[type="checkbox"]')?.disabled)
    const originalA = await a.isChecked(), originalB = await b.isChecked()
    await page.evaluate(() => window.datasetQa.holdProfile(true))
    await a.click()
    await page.waitForFunction(() => window.datasetQa.profileCalls().length === 1)
    assert(await b.isEnabled(), 'Saving one rule must keep other checkboxes interactive')
    assert(await dialog.locator('.vc-profile-footer').getByRole('button', { name: '关闭', exact: true }).isEnabled(), 'A profile save must not disable the entire footer')
    await b.click(); await a.click()
    assert(await a.isChecked() === originalA && await b.isChecked() !== originalB, 'The latest checkbox values must appear before their acknowledgements')
    assert(await page.evaluate(() => window.datasetQa.profileCalls().length) === 1, 'Edits during an in-flight save must wait for its immutable profile receipt')
    await page.evaluate(() => window.datasetQa.releaseProfile())
    await page.waitForFunction(() => window.datasetQa.profileCalls().length === 2 && document.querySelector('.vc-profile-save-state')?.textContent.includes('已自动保存'))
    const writes = await page.evaluate(() => window.datasetQa.profileCalls())
    assert(writes[1].changes.length === 2 && writes[1].expectedProfileId === 'qa-profile-1', 'Later edits must coalesce and use the acknowledged profile identity')
    await page.evaluate(() => window.datasetQa.loseProfileAck())
    await a.click(); await dialog.getByRole('alert').waitFor()
    const beforeRetry = await page.evaluate(() => window.datasetQa.profileCalls().at(-1).operationId)
    await dialog.getByRole('button', { name: '关闭', exact: true }).first().click()
    await dialog.waitFor({ state: 'hidden' })
    await page.getByRole('button', { name: '查看完整档案', exact: true }).click(); await dialog.getByRole('alert').waitFor()
    await dialog.getByRole('button', { name: '重试', exact: true }).click()
    await page.waitForFunction(() => !document.querySelector('.vc-profile-dialog [role="alert"]') && document.querySelector('.vc-profile-save-state')?.textContent.includes('已自动保存'))
    assert(await page.evaluate(() => window.datasetQa.profileCalls().at(-1).operationId) === beforeRetry, 'Reopening must preserve an unconfirmed save identity for explicit retry')
    await page.evaluate(() => window.datasetQa.holdProfile(true))
    await a.click()
    await page.waitForFunction(() => window.datasetQa.profileCalls().length === 5)
    await dialog.getByRole('button', { name: '生成数据集', exact: true }).click()
    assert(await page.evaluate(() => window.datasetQa.exportedProfiles().length) === 0, 'Dataset generation must wait for all queued edits to be acknowledged')
    await page.evaluate(() => window.datasetQa.releaseProfile())
    await page.waitForFunction(() => window.datasetQa.exportedProfiles().length === 1)
    assert(await page.evaluate(() => window.datasetQa.exportedProfiles()[0] === window.datasetQa.profile().id), 'Dataset generation must use the final saved profile')
    await dialog.locator('.vc-profile-footer').getByRole('button', { name: '关闭', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' }); await page.evaluate(() => window.datasetQa.acknowledge())
    await page.evaluate(() => window.datasetQa.enablePaging())
    await page.getByRole('tab', { name: '数据集', exact: true }).click()
    await page.locator('[data-dataset-row]').first().getByRole('button', { name: '详情', exact: true }).click()
    const detail = page.getByRole('dialog', { name: '数据集详情', exact: true })
    await detail.getByRole('tab', { name: '逐图观察', exact: true }).click()
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length === 5)
    const scroll = detail.locator('.vc-dataset-detail-scroll')
    await page.evaluate(() => window.datasetQa.failSamplePage(true))
    await scroll.evaluate(element => { element.scrollTop = element.scrollHeight })
    await detail.getByRole('alert').waitFor()
    assert(await detail.locator('.vc-dataset-sample').count() === 5, 'A failed next page must keep the saved observations visible')
    await scroll.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))))
    assert(await page.evaluate(() => window.datasetQa.sampleReads().length) === 2, 'Automatic pagination must stop after failure until an explicit retry')
    await page.evaluate(() => window.datasetQa.failSamplePage(false))
    await detail.getByRole('button', { name: '重试', exact: true }).click()
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length >= 10)
    await scroll.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length === 13)
    const reads = await page.evaluate(() => window.datasetQa.sampleReads())
    assert(JSON.stringify(reads) === JSON.stringify(['first', '5', '5', '10']), 'Each page cursor must advance once; retry must reuse the failed cursor')
    assert(await detail.getByRole('button', { name: /加载更多/ }).count() === 0, 'The final sample page must end automatic loading')
    assert(errors.length === 0, 'Profile editing and pagination must not produce uncaught browser errors')
    const result = { responsiveRuleEdits: true, coalescedFirstSaves: 2, immutableReceiptOrdering: true, unknownAcknowledgementRetained: true, retryOperationIdentity: true, generationUsesSavedProfile: true, closeBeforeExportAcknowledgement: true, automaticSamplePages: [5, 10, 13], sampleFailureRetainsRows: true, sameCursorRetry: true, productionWrites: 0, pageErrors: errors }
    const expected = await (await page.request.get(new URL('profile-dataset-ui.expected.json', page.url()).href)).json()
    assert(JSON.stringify(result) === JSON.stringify(expected), 'Observable behavior must match its owner-local snapshot')
    return result
  } finally { page.off('pageerror', onError) }
}
